import {getAppServices} from './app-services.js';
import {MUSIC_ALBUMS,ALBUM_TIERS,albumById,editionById} from './music-albums.js';
import {RECORDED_ALBUM_ART} from './recorded-album-art.js';
import {createRecordedAlbumPlayer} from './recorded-album-player.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=n=>Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');
const cover=a=>RECORDED_ALBUM_ART[a.coverKey]?`<img src="${esc(RECORDED_ALBUM_ART[a.coverKey])}" alt="Capa de ${esc(a.title)}">`:`<span class="album-cover" aria-hidden="true"><span class="album-vinyl"></span><span class="album-initials">${esc(a.title.split(' ').map(w=>w[0]).slice(0,3).join(''))}</span></span>`;
export function mountRecordedAlbums(shadow,{stopRecordsPreview}){
 const root=shadow.querySelector('#gv-vitrola-service'),win=root.querySelector('.window'),legacy=[...win.children].filter(e=>!e.classList.contains('head')),doc=root.ownerDocument;
 const css=doc.createElement('link');css.rel='stylesheet';css.href='recorded-albums-ui.css';shadow.append(css);
 const tabs=doc.createElement('nav');tabs.className='album-tabs';tabs.setAttribute('aria-label','Bibliotecas da vitrola');tabs.innerHTML='<button type="button" class="button" data-library="records" aria-pressed="false">Discos da expedição</button><button type="button" class="button" data-library="albums" aria-pressed="true">Álbuns · 11</button>';
 const panel=doc.createElement('section');panel.className='recorded-albums';panel.setAttribute('aria-label','Álbuns de músicas');panel.innerHTML='<div class="album-toolbar"><label>Dificuldade <select aria-label="Filtrar álbuns por dificuldade" id="album-tier"><option value="Todos">Todos os níveis</option>'+Object.entries(ALBUM_TIERS).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')+'</select></label><span>11 álbuns · 16 versões</span></div><div class="album-layout"><nav class="album-grid" aria-label="Escolher álbum"></nav><section class="album-detail" aria-label="Ouvir álbum"></section></div><p class="album-status" role="status" aria-live="polite"></p>';
 root.querySelector('.head').after(tabs);tabs.after(panel);const q=s=>panel.querySelector(s),player=createRecordedAlbumPlayer({audio:getAppServices().audio,editionById});let selected=MUSIC_ALBUMS[0].id,currentEdition=MUSIC_ALBUMS[0].editions[0].id,tier='Todos',frame=0,disposed=false,mode='albums';
 function grid(){q('.album-grid').innerHTML=MUSIC_ALBUMS.filter(a=>tier==='Todos'||a.editions.some(e=>e.tier===tier)).map(a=>`<button type="button" class="disc-card album-card" data-album="${a.id}" aria-pressed="${a.id===selected}">${cover(a)}<strong>${esc(a.title)}</strong><small>${esc(a.artist)}</small><span class="album-levels">${[...new Set(a.editions.map(e=>ALBUM_TIERS[e.tier]))].join(' · ')}</span></button>`).join('');}
 function detail(){const a=albumById(selected),e=editionById(currentEdition);q('.album-detail').innerHTML=`<div class="album-detail-cover">${cover(a)}</div><h3>${esc(a.title)}</h3><p class="album-artist">${esc(a.artist)} · ${a.genre}</p><p>${esc(a.description)}</p><label class="album-edition">Versão <select id="album-edition" aria-label="Versão do álbum">${a.editions.map(v=>`<option value="${v.id}" ${v.id===e.id?'selected':''}>${ALBUM_TIERS[v.tier]} · ${esc(v.label)}</option>`).join('')}</select></label><p class="album-version-info">${ALBUM_TIERS[e.tier]} · ${e.duration.toFixed(1).replace('.',',')} s por volta · ${e.actions} ações</p><button type="button" class="button primary" id="album-play">▶ Ouvir álbum</button><label class="album-seek-label">Posição <input type="range" id="album-seek" aria-label="Posição da música" min="0" max="${e.duration}" step="0.01" value="0"><output id="album-position">0:00 / ${time(e.duration)}</output></label><p class="album-credit"><a href="${esc(a.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(a.artist)}</a> · <a href="${a.licenseUrl}" target="_blank" rel="noopener noreferrer">CC BY 4.0</a><br>Trecho em loop preparado para GemVenture. <a href="${e.mapUrl}" download>Mapa de batidas</a> · <a href="assets/audio/approved-library-r5/CREDITOS.txt" target="_blank" rel="noopener">Créditos e alterações</a></p>`;progress();}
 function progress(){const s=player.getState(),active=s.editionId===currentEdition,playing=active&&s.status==='playing',b=q('#album-play');if(!b)return;b.textContent=playing?'Ⅱ Pausar':active&&s.status==='loading'?'Carregando…':active&&s.status==='paused'?'▶ Continuar':'▶ Ouvir álbum';b.disabled=active&&s.status==='loading';b.setAttribute('aria-pressed',String(playing));q('#album-seek').value=active?s.elapsed:0;q('#album-position').textContent=time(active?s.elapsed:0)+' / '+time(active?s.duration:editionById(currentEdition).duration);q('.album-status').textContent=s.error||'';}
 function setMode(next){player.stop();stopRecordsPreview();mode=next;legacy.forEach(e=>e.hidden=mode==='albums');panel.hidden=mode!=='albums';tabs.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.library===mode)));}
 tabs.addEventListener('click',e=>{const b=e.target.closest('[data-library]');if(b)setMode(b.dataset.library);});
 panel.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.album){player.stop();stopRecordsPreview();selected=b.dataset.album;const a=albumById(selected);currentEdition=(a.editions.find(e=>e.tier===tier)||a.editions[0]).id;grid();detail();q('#album-play').focus({preventScroll:true});}else if(b.id==='album-play'){const s=player.getState();if(s.status==='playing')player.pause();else{if(s.status!=='paused')stopRecordsPreview();void player.play(currentEdition);}}});
 panel.addEventListener('change',e=>{if(e.target.id==='album-tier'){player.stop();stopRecordsPreview();tier=e.target.value;const available=MUSIC_ALBUMS.filter(a=>tier==='Todos'||a.editions.some(e=>e.tier===tier));if(!available.some(a=>a.id===selected))selected=available[0].id;const a=albumById(selected);currentEdition=(a.editions.find(e=>e.tier===tier)||a.editions[0]).id;grid();detail();}else if(e.target.id==='album-edition'){player.stop();currentEdition=e.target.value;detail();q('#album-edition').focus();}});
 panel.addEventListener('input',e=>{if(e.target.id==='album-seek')player.seek(Number(e.target.value));});
 const unsubscribe=player.subscribe(progress),visibility=()=>{if(doc.hidden)player.stop();};doc.addEventListener('visibilitychange',visibility);const tick=()=>{if(disposed)return;if(mode==='albums'&&player.getState().status==='playing')progress();frame=requestAnimationFrame(tick);};
 grid();detail();setMode('albums');frame=requestAnimationFrame(tick);
 return {dispose(){disposed=true;cancelAnimationFrame(frame);doc.removeEventListener('visibilitychange',visibility);unsubscribe();player.dispose();css.remove();tabs.remove();panel.remove();legacy.forEach(e=>e.hidden=false);}};
}
